use crate::aap::caps::http_client::fetch;

/// Hosts this node's `HTTPClient<[...]>` handle is scoped to. Checked here so
/// that an off-list URL becomes a recorded failure instead of a boundary trap
/// that would abort the whole run.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extract the lowercased host from an http(s) URL. Returns `None` for
/// anything that does not parse cleanly; such URLs are treated as not permitted.
fn host_of(url: &str) -> Option<String> {
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let authority = rest.split(['/', '?', '#']).next()?;
    // Drop any userinfo ("user:pass@host").
    let host_port = authority.rsplit('@').next()?;
    // IPv6 literals are never on the allowlist.
    if host_port.starts_with('[') {
        return None;
    }
    let host = host_port.split(':').next()?;
    if host.is_empty() {
        None
    } else {
        Some(host.to_ascii_lowercase())
    }
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            match host_of(&url) {
                Some(host) if ALLOWED_HOSTS.contains(&host.as_str()) => {
                    match fetch(&url) {
                        Ok(body) => documents.push(FeedDocument { url, body }),
                        Err(error) => failures.push(FetchFailure { url, error }),
                    }
                }
                _ => failures.push(FetchFailure {
                    url,
                    error: "host not permitted or unparseable".to_string(),
                }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
